}
float ik_vn() {
  return 32.0 + 16.0 * step(384.0, texsize.x) * step(337.0, texsize.y) + 16.0 * step(576.0, texsize.x) * step(513.0, texsize.y)
       + 32.0 * step(1080.0, texsize.x) * step(961.0, texsize.y);
